import re

PROCESS = re.compile(r"^Attaching to process ID (?P<pid>\d+), please wait")
JVM = re.compile(r"^JVM version is (?P<v>\S+)\s*$")
COMPILER = re.compile(r"^(?P<c>\S.*?) compiler detected\.\s*$")
ALLOC = re.compile(r"^using (?P<a>\S.*?) object allocation\.\s*$")
GC = re.compile(r"^(?P<collector>\S.*?) GC with (?P<threads>\d+) thread\(s\)\s*$")
TITLE = re.compile(r"^(?P<title>\S[^=]*?):\s*$")
CONFIG = re.compile(r"^\s+(?P<name>[A-Z]\w*)\s+= (?P<value>[\d.]+(?: \w+)?)(?: \((?P<mb>[\d.]+MB)\))?\s*$")
USAGE = re.compile(r"^\s+(?P<name>[a-z]\w*)\s+= (?P<value>[\d.]+(?: \w+)?)(?: \((?P<mb>[\d.]+MB)\))?\s*$")
PCT = re.compile(r"^\s+(?P<pct>[\d.]+%) used\s*$")
NOISE = re.compile(r"^Debugger attached successfully\.")


def parse(lines):
    skip, proc, proc_lines = [], {}, []
    collectors, coll_lines = [], []
    config, config_lines = [], []
    spaces, space_lines = [], []
    section, generation, cur = "", "", None

    def close():
        if cur is not None and len(cur) > 2:
            spaces.append(cur)

    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = PROCESS.match(ln)
        if m:
            proc["process ID"] = m.group("pid"); proc_lines.append(i); continue
        m = JVM.match(ln)
        if m:
            proc["JVM version"] = m.group("v"); proc_lines.append(i); continue
        m = COMPILER.match(ln)
        if m:
            proc["compiler"] = m.group("c"); proc_lines.append(i); continue
        m = ALLOC.match(ln)
        if m:
            proc["object allocation"] = m.group("a"); proc_lines.append(i); continue
        m = GC.match(ln)
        if m:
            collectors.append({"collector": m.group("collector"), "threads": m.group("threads")})
            coll_lines.append(i); continue
        if NOISE.match(ln):
            skip.append(i); continue
        m = TITLE.match(ln)
        if m:
            title = m.group("title")
            if title in ("Heap Configuration", "Heap Usage"):
                section = title; skip.append(i); continue
            close()
            if "generation" in title.lower():
                generation = title
            cur = {"generation": generation, "space": title}
            space_lines.append(i)
            continue
        if section == "Heap Configuration":
            m = CONFIG.match(ln)
            if m:
                config.append({"name": m.group("name"), "value": m.group("value"), "MB": m.group("mb") or ""})
                config_lines.append(i); continue
        if cur is not None:
            m = USAGE.match(ln)
            if m:
                cur[m.group("name")] = m.group("value")
                if m.group("mb"):
                    cur[m.group("name") + " MB"] = m.group("mb")
                space_lines.append(i); continue
            m = PCT.match(ln)
            if m:
                cur["% used"] = m.group("pct"); space_lines.append(i); continue
    close()
    keys = []
    for r in spaces:
        for k in r:
            if k not in keys:
                keys.append(k)
    spaces = [{k: r.get(k, "") for k in keys} for r in spaces]
    blocks = [
        {"name": "process", "kind": "kv", "lines": proc_lines, "records": [proc]},
        {"name": "collector", "kind": "table", "lines": coll_lines, "records": collectors},
        {"name": "heap configuration", "kind": "table", "lines": config_lines, "records": config},
        {"name": "heap usage", "kind": "table", "lines": space_lines, "records": spaces},
    ]
    return {"blocks": blocks, "skip": skip}
